"use client";

import { useState } from "react";
import { ChevronDown, Network, Scale, Waypoints } from "lucide-react";
import type { ReportGraphs } from "@/types";
import { RelationshipGraph } from "@/components/investigations/RelationshipGraph";
import { InvestigationTimeline } from "@/components/investigations/InvestigationTimeline";

interface InvestigationGraphsProps {
  graphs?: ReportGraphs | null;
}

/**
 * Report-level graph visualizations: entity/relationship graph and
 * timeline are the primary views; the reasoning and decision-comparison
 * graphs share the same GraphData shape and live in a collapsible
 * <details> section.
 *
 * That section is expanded by default whenever the backend actually supplies
 * the graphs: the reasoning graph traces hypotheses through evidence,
 * compliance and decision, which is the part of the report reviewers look for,
 * and collapsing it by default made it look like it had stopped being
 * generated. Open state is held in React rather than left to the DOM so that
 * a collapse survives the investigation page's polling re-renders.
 */
export function InvestigationGraphs({ graphs }: InvestigationGraphsProps) {
  const hasSecondaryGraphs = Boolean(
    graphs?.reasoning_graph?.nodes.length || graphs?.decision_comparison_graph?.nodes.length,
  );
  const [secondaryOpen, setSecondaryOpen] = useState(true);

  return (
    <section
      className="rounded-xl border border-gray-200 bg-white shadow-sm dark:border-gray-800 dark:bg-gray-900"
      aria-labelledby="investigation-graphs-title"
    >
      <div className="flex items-center gap-3 border-b border-gray-100 px-6 py-4 dark:border-gray-800">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-300">
          <Network className="h-5 w-5" />
        </div>
        <h3 id="investigation-graphs-title" className="text-base font-semibold text-gray-900 dark:text-white">
          Investigation Graphs
        </h3>
      </div>

      <div className="space-y-8 px-6 py-5">
        <RelationshipGraph
          title="Entity Relationship Graph"
          icon={Waypoints}
          data={graphs?.entity_relationship_graph}
          emptyMessage="No relationship data available for this investigation."
        />

        <div className="border-t border-gray-100 pt-6 dark:border-gray-800">
          <InvestigationTimeline events={graphs?.investigation_timeline} />
        </div>

        {hasSecondaryGraphs && (
          <details
            className="group border-t border-gray-100 pt-6 dark:border-gray-800"
            open={secondaryOpen}
            onToggle={(event) => setSecondaryOpen(event.currentTarget.open)}
          >
            <summary className="flex cursor-pointer list-none items-center gap-1.5 text-sm font-medium text-gray-600 hover:text-gray-900 dark:text-gray-300">
              <ChevronDown className="h-4 w-4 transition-transform group-open:rotate-180" />
              Reasoning &amp; decision graphs
            </summary>
            <div className="mt-4 space-y-8">
              <RelationshipGraph
                title="Reasoning Graph"
                icon={Waypoints}
                data={graphs?.reasoning_graph}
                emptyMessage="No reasoning graph data available for this investigation."
              />
              <RelationshipGraph
                title="Decision Comparison Graph"
                icon={Scale}
                data={graphs?.decision_comparison_graph}
                emptyMessage="No decision comparison graph data available for this investigation."
              />
            </div>
          </details>
        )}
      </div>
    </section>
  );
}
